comms.text:
@1 אַתּוּן קָיְמִין יוֹמָא דֵין כֻּלְכוֹן קֳדָם יְיָ אֱלָהֲכוֹן רֵישֵׁיכוֹן שִׁבְטֵיכוֹן סָבֵיכוֹן וְסָרְכֵיכוֹן כָּל אֱנַשׁ יִשְׂרָאֵל:
@2 טַפְלְכוֹן נְשֵׁיכוֹן וְגִיוֹרָךְ דִי בְּגוֹ מַשְׁרִיתָךְ מִלָקֵטּ אָעָיךְ עַד מְלֵי מַיָיךְ:
@3 לְאָעָלוּתָךְ בִּקְיָמָא דַיְיָ אֱלָהָךְ וּבְמוֹמָתֵהּ דִי יְיָ אֱלָהָךְ גְזַר עִמָךְ יוֹמָא דֵין:
@4 בְּדִיל לַאֲקָמָא יָתָךְ יוֹמָא דֵין קֳדָמוֹהִי לְעַמָא וְהוּא יְהֵי לָךְ לֶאֶלָהּ כְּמָא דִי מַלִיל לָךְ וּכְמָא דִי קַיִים לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב:
@5 וְלָא עִמְכוֹן בִּלְחוֹדֵיכוֹן אֲנָא גְזַר יָת קְיָמָא הָדָא וְיָת מוֹמָתָא הָדָא:
@6 אֲרֵי יָת מָן דְאִיתוֹהִי הָכָא עִמָנָא קָאֵם יוֹמָא דֵין קֳדָם יְיָ אֱלָהָנָא וְיָת מָן דְלֵיתוֹהִי הָכָא עִמָנָא יוֹמָא דֵין:
@7 אֲרֵי אַתּוּן יְדַעְתּוּן יָת דִיתֵבְנָא בְּאַרְעָא דְמִצְרָיִם וְיָת דִי עֲבַרְנָא בְּגוֹ עַמְמַיָא דִי עֲבַרְתּוּן:
@8 וַחֲזֵיתוּן יָת שִׁקוּצֵיהוֹן וְיָת טַעֲוָתְהוֹן אָעָא וְאַבְנָא כַּסְפָּא וְדַהֲבָא דִי עִמְהוֹן:
@9 דִילְמָא אִית בְּכוֹן גְבַר אוֹ אִתְּתָא אוֹ זַרְעִית אוֹ שִׁבְטָא דִי לִבֵּהּ פָּנֵי יוֹמָא דֵין מִדַחַלְתָּא דַייָ אֱלָהָנָא לִמְהַךְ לְמִפְלַח יָת טַעֲוַת עַמְמַיָא הָאִנוּן דִילְמָא אִית בְּכוֹן גְבַר מְהַרְהַר חֶטְאִין אוֹ זָדוֹן:
@10 וִיהֵי בְּמִשְׁמְעֵהּ יָת פִּתְגָמֵי מוֹמָתָא הָדָא וִיחַשַׁב בְּלִבֵּהּ לְמֵימַר שְׁלָמָא יְהֵי לִי אֲרֵי בְּהַרְהוֹר לִבִּי אֲנָא אָזֵל בְּדִיל לְאוֹסָפָא לֵהּ חֶטְאֵי שָׁלוּתָא עַל זְדָנוּתָא:
@11 לָא יֵיבֵי יְיָ לְמִשְׁבַּק לֵהּ אֲרֵי בְּכֵן יִתְקֵף רָגְזָא דַיְיָ וְחֶמְתֵהּ בְּגַבְרָא הַהוּא וְיִדְבְּקוּן בֵּהּ כָּל לְוָטַּיָא דִכְתִיבִין בְּסִפְרָא הָדֵין וְיִמְחֵי יְיָ יָת שְׁמֵהּ מִתְּחוֹת שְׁמַיָא:
@12 וְיַפְרְשִׁנֵהּ יְיָ לְבִישָׁא מִכֹּל שִׁבְטַיָא דְיִשְׂרָאֵל כְּכֹל לְוָטֵי קְיָמָא דִכְתִיבִין בְּסִפְרָא דְאוֹרַיְתָא הָדֵין:
@13 וְיֵימַר דָרָא בַתְרָאָה בְּנֵיכוֹן דִי יְקוּמוּן מִבַּתְרֵיכוֹן וּבַר עַמְמִין דִי יֵיתֵי מֵאַרְעָא רְחִיקָא וְיֶחֱזוּן יָת מְחָתָא דְאַרְעָא הַהִיא וְיָת מַרְעָהָא דִי אַמְרַע יְיָ בַּהּ:
@14 גָפְרֵתָא וּמִלְחָא יְקִידַת כָּל אַרְעַהּ לָא תִזְרַע וְלָא תַצְמַח וְלָא יִסַק בַּהּ כָּל עֶסְבָּא כְּמַהְפֶּכְתָּא דִסְדֹם וַעֲמֹרָה אַדְמָה וּצְבוֹיִם דִי הֲפַךְ יְיָ בְּרָגְזֵהּ וּבְחֶמְתֵהּ:
@15 וְיֵימְרוּן כָּל עַמְמַיָא עַל מֶה עֲבַד יְיָ כְּדֵין לְאַרְעָא הָדָא מָא תְקוֹף רָגְזָא רַבָּא הָדֵין:
@16 וְיֵימְרוּן עַל דִשְׁבָקוּ יָת קְיָמָא דַיְיָ אֱלָהָא דַאֲבָהָתְהוֹן דִי גְזַר עִמְהוֹן בְּאַפָּקוּתֵהּ יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם:
@17 וַאֲזָלוּ וּפְלָחוּ לְטַעֲוַת עַמְמַיָא וּסְגִידוּ לְהוֹן דַחֲלָן דִי לָא יְדָעֻנוּן וְלָא אוֹטִיבָא לְהוֹן:
@18 וּתְקֵף רָגְזָא דַיְיָ בְּאַרְעָא הַהִיא לְאַיְתָאָה עֲלַהּ יָת כָּל לְוָטַיָא דִכְתִיבִין בְּסִפְרָא הָדֵין:
@19 וְטַּלְטְּלִנוּן יְיָ מֵעַל אַרְעֲהוֹן בִּרְגַז וּבְחֵמְתָא וּבִתְקוֹף רְגַז וְאַגְלִנוּן לְאַרְעָא אָחֳרִי כְּיוֹמָא הָדֵין:
@20 דְמִטַמְרָן קֳדָם יְיָ אֱלָהָנָא וּדְמִגַלְיָן לָנָא וְלִבְנָנָא עַד עֳלָם לְמֶעְבַּד יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא:
@21 וִיהֵי אֲרֵי יֵיתוּן עֲלָךְ כָּל פִּתְגָמַיָא הָאִלֵין בִּרְכָן וּלְוָטִין דִי יְהָבִית קֳדָמָךְ וּתְתוּב לְלִבָּךְ בְּכָל עַמְמַיָא דִי אַגְלָךְ יְיָ אֱלָהָךְ לְתַמָן:
@22 וּתְתוּב לְדַחַלְתָּא דַיְיָ אֱלָהָךְ וּתְקַבֵּל לְמֵימְרֵהּ כְּכֹל דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין אַתְּ וּבְנָיךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@23 וִיתוּב יְיָ אֱלָהָךְ יָת שְׁבִי גַלְוָתָךְ וִירַחַם עֲלָךְ וִיתוּב וְיִכְנְשִׁנָךְ מִכָּל עַמְמַיָא דִי בַדְרָךְ יְיָ אֱלָהָךְ לְתַמָן:
@24 אִם יְהֵי גַלְוָתָךְ בִּסְיָפֵי שְׁמַיָא מִתַּמָן יִכְנְשִׁנָךְ יְיָ אֱלָהָךְ וּמִתַּמָן יְקָרְבִנָךְ:
@25 וְיָעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִירִיתוּ אֲבָהָתָךְ וְתֵרְתַהּ וְיוֹטֶב לָךְ וְיַסְגִנָךְ מֵאֲבְהָתָךְ:
@26 וְיֶעְדֵי יְיָ אֱלָהָךְ יָת טַפְשׁוּת לִבָּךְ וְיָת טַּפְשׁוּת לִבָּא דִבְנָיךְ לְמִרְחַם יָת יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ בְּדִיל חַיָיךְ:
@27 וְיִתֵּן יְיָ אֱלָהָךְ יָת כָּל לְוָטַיָא הָאִלֵין עַל בַּעֲלֵי דְבָבָךְ וְעַל סָנְאָךְ דִי רְדָפוּךְ:
@28 וְאַתְּ תְּתוּב וּתְקַבַּל לְמֵימְרָא דַיְיָ וְתַעְבֵּד יָת כָּל פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@29 וְיוֹתְרִינָךְ יְיָ אֱלָהָךְ בְּכֹל עוֹבָדֵי יְדָךְ בְּוַלְדָא דִמְעָךְ וּבְוַלְדָא דִבְעִירָךְ וּבְאִבָּא דְאַרְעָךְ לְטָּבָא אֲרֵי יְתוּב יְיָ לְמֶחֱדֵי עֲלָךְ לְטָב כְּמָא דִי חֲדִי עַל אֲבָהָתָךְ:
@30 אֲרֵי תְקַבַּל בְּמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר פִּקוּדוֹהִי וּקְיָמוֹהִי דִכְתִיבִין בְּסִפְרָא דְאוֹרַיְתָא הָדֵין אֲרֵי תְתוּב קֳדָם יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@31 אֲרֵי תַּפְקֶדְתָּא הָדָא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לָא מַפְרְשָׁא הִיא מִנָךְ וְלָא רְחִיקָא הִיא:
@32 לָא בִשְׁמַיָא הִיא לְמֵימָר מָן יִסַק לָנָא לִשְׁמַיָא וְיִסְבַהּ לָנָא וְיַשְׁמְעִנָנָא יָתַהּ וְנַעְבְּדִנַהּ:
@33 וְלָא מֵעִבְרָא לְיַמָא הִיא לְמֵימַר מָן יֵעִבַר לָנָא לְעִבְרָא דְיַמָא וְיִסְבַהּ לָנָא וְיַשְׁמְעִנָנָא יָתַהּ וְנַעְבְּדִנַהּ:
@34 אֲרֵי קָרִיב לָךְ פִּתְגָמָא לַחֲדָא בְּפוּמָךְ וּבְלִבָּךְ לְמֶעְבְּדֵהּ:
@35 חֲזֵי דִיהָבִית קֳדָמָךְ יוֹמָא דֵין יָת חַיֵי וְיָת טַבְתָא וְיָת מוֹתָא וְיָת בִּישָׁא:
@36 דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמִרְחַם יָת יְיָ אֱלָהָךְ לִמְהַךְ בְּאָרְחָן דְתָקְנָן קֳדָמוֹהִי וּלְמִטַר פִּקוּדוֹהִי וּקְיָמוֹהִי וְדִינוֹהִי וְתֵיחֵי וְתִסְגֵי וִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּאַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ:
@37 וְאִם יִפְנֵי לִבָּךְ וְלָא תְקַבֵּל וְתִטְּעֵי וְתִסְגוּד לְטַּעֲוַת עַמְמַיָא וְתִפְלְחִנוּן:
@38 חַוֵיתִי לְכוֹן יוֹמָא דֵין אֲרֵי מֵיבַד תֵּיבְדוּן לָא תוֹרְכוּן יוֹמִין עַל אַרְעָא דִי אַתְּ עָבֵר יָת יַרְדְנָא לְמֵעַל לְתַמָן לְמֵירְתַהּ:
@39 אַסְהֵדִית בְּכוֹן יוֹמָא דֵין יָת שְׁמַיָא וְיָת אַרְעָא חַיֵי וּמוֹתָא יְהָבִית קֳדָמָךְ בִּרְכָן וּלְוָטִין וְתִתִּרְעֵי בְּחַיֵי בְּדִיל דְתֵיחֵי אַתְּ וּבְנָיךְ:
@40 לְמִרְחַם יָת יְיָ אֱלָהָךְ לְקַבָּלָא לְמֵימְרֵהּ וּלְאִתְקְרָבָא לְדַחַלְתֵּהּ אֲרֵי הוּא חַיָיךְ וְאוֹרָכוּת יוֹמָיךְ לְמִתַּב עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמִתַּן לְהוֹן: פפפ:

@1 **אתם נצבים.** מלמד שכנסם משה לפני הקדוש ברוך הוא ביום מותו להכניסם בברית: **ראשיכם שבטיכם.** ראשיכם לשבטיכם: **זקניכם ושטריכם.** החשוב חשוב קודם, ואחר כך כל איש ישראל:
@2 **מחטב עציך.** מלמד שבאו כנענים להתגיר בימי משה, כדרך שבאו גבעונים בימי יהושע. וזהו האמור בגבעונים (יהושע ט, ד) ויעשו גם המה בערמה, ונתנם משה חוטבי עצים ושואבי מים:
@3 **לעברך.** להיותך עובר בברית. ולא יתכן לפרשו כמו להעבירך, אלא כמו (לעיל ד, יד) לעשותכם אותם: **לעברך בברית.** דרך העברה, כך היו כורתים ברית, עושין מחצה מכאן ומחצה מכאן ועוברים בנתים, כמו שנאמר (ירמיה לד, יח) העגל אשר כרתו לשנים ויעברו בין בתריו:
@4 **למען הקים אתך היום לו לעם.** כל כך הוא נכנס לטרוח למען קים אתך לפניו לעם: **והוא יהיה לך לאלהים.** לפי שדבר לך ונשבע לאבותיך שלא להחליף את זרעם באמה אחרת, לכך הוא אוסר אתכם בשבועות הללו, שלא תקניטוהו אחר שהוא אינו יכול להבדל מכם. עד כאן פרשתי לפי פשוטו של פרשה. ומדרש אגדה, למה נסמכה פרשת אתם נצבים לקללות, לפי ששמעו ישראל מאה קללות חסר שתים, חוץ ממ''ט שבתורת כהנים, הוריקו פניהם ואמרו מי יוכל לעמוד באלו, התחיל משה לפיסם אתם נצבים היום, הרבה הכעסתם למקום ולא עשה אתכם כליה והרי אתם קימים לפניו: **היום.** כיום הזה שהוא קים והוא מאפיל ומאיר, כך האיר לכם וכך עתיד להאיר לכם, והקללות והיסורין מקימין אתכם ומציבין אתכם לפניו. ואף הפרשה של מעלה מזו פיוסין הם (לעיל פסוק א') , אתם ראיתם את כל אשר עשה. דבר אחר, אתם נצבים. לפי שהיו ישראל יוצאין מפרנס לפרנס ממשה ליהושע, לפיכך עשה אותם מצבה כדי לזרזם. וכן עשה יהושע, וכן שמואל (שמואל א' יב, ז) התיצבו ואשפטה אתכם, כשיצאו מידו ונכנסו לידו של שאול:
@6 **ואת אשר איננו פה.** ואף עם דורות העתידים להיות:
@7 **כי אתם ידעתם** וגו' **ותראו את שקוציהם.** לפי שראיתם האמות עובדי עבודה זרה ושמא השיא לב אחד מכם אותו ללכת אחריהם, פן יש בכם וגו' (פסוק יז) לפיכך אני צריך להשביעכם:
@8 **ותראו את שקוציהם.** על שם שהם מאוסים כשקצים: **גלליהם.** שמסרחים ומאוסין כגלל: **עץ ואבן.** אותן של עצים ושל אבנים ראיתם בגלוי, לפי שאין הגוים יראים שמא יגנבו, אבל של כסף וזהב, עמהם, בחדרי משכיתם הם, לפי שהם יראים שמא יגנבו:
@9 **פן יש בכם.** שמא יש בכם: **אשר לבבו פנה היום.** מלקבל עליו הברית: **שרש פרה ראש ולענה.** שרש מגדל עשב מר כגידין, שהם מרים, כלומר מפרה ומרבה רשע בקרבכם:
@10 **והתברך בלבבו.** לשון ברכה, יחשב בלבו ברכת שלום לעצמו לאמר, לא יבואוני קללות הללו, אך שלום יהיה לי: **והתברך.** בינדיר''א שי''י בלע''ז [יברך את עצמו] , כמו והתגלח והתפלל: **בשררות לבי אלך.** במראית לבי, כמו (במדבר כד, יז) אשורנו ולא קרוב, כלומר מה שלבי רואה לעשות: **למען ספות הרוה.** לפי שאוסיף לו פרענות על מה שעשה עד הנה בשוגג והייתי מעביר עליהם, וגורם עתה שאצרפם עם המזיד ואפרע ממנו הכל. וכן תרגם אנקלוס בדיל לאוספא ליה חטאי שלותא על זדנותא, שאוסיף לו אני השגגות על הזדונות: **הרוה.** שוגג שהוא עושה כאדם שכור שלא מדעת: **הצמאה.** שהוא עושה מדעת ובתאוה:
@11 **יעשן אף ה'.** על ידי כעס הגוף מתחמם והעשן יוצא מן האף, וכן (ש''ב כב, ט) עלה עשן באפו, ואף על פי שאין זו לפני המקום, הכתוב משמיע את האזן כדרך שהיא רגילה ויכולה לשמוע, כפי דרך הארץ: **וקנאתו.** לשון חמה אנפרטמינ''ט [חמה] אחיזת לבישת נקמה, ואינו מעביר על המדה:
@12 **הכתובה בספר התורה הזה.** ולמעלה הוא אומר (לעיל כח, סא) בספר התורה הזאת גם כל חלי וכל מכה וגו' , הזאת, לשון נקבה, מוסב על התורה. הזה, לשון זכר, מוסב על הספר, ועל ידי פסוק הטעמים הן נחלקין לשתי לשונות, בפרשת הקללות הטפחא נתונה תחת בספר, והתורה הזאת דבוקים זה לזה, לכך אמר הזאת, וכאן הטפחה נתונה תחת התורה, נמצא ספר התורה דבוקים זה לזה, לפיכך לשון זכר נופל אחריו, שהלשון נופל על הספר:
@17 **לא ידעום.** לא ידעו בהם גבורת אלהות: **ולא חלק להם.** לא נתנם לחלקם. ואונקלוס תרגם ולא אוטיבא להון, לא הטיבו להם שום טובה, ולשון לא חלק אותו אלוה שבחרו להם, לא חלק להם שום נחלה ושום חלק:
@19 **ויתשם ה'.** כתרגומו וטלטלנון, וכן (ירמיה יב, יד) הנני נותשם מעל אדמתם:
@20 **הנסתרת לה' אלהינו.** ואם תאמרו מה בידינו לעשות, אתה מעניש את הרבים על הרהורי היחיד, שנאמר (פסוק יז) פן יש בכם איש וגו' , ואחר כך (פסוק כא) וראו את מכות הארץ ההיא, והלא אין אדם יודע טמונותיו של חברו, אין אני מעניש אתכם על הנסתרות, שהן לה' אלהינו והוא יפרע מאותו יחיד, אבל הנגלות' לנו ולבנינו לבער הרע מקרבנו, ואם לא נעשה דין בהם יענשו הרבים. נקוד על לנו ולבנינו, לדרוש, שאף על הנגלות לא ענש את הרבים עד שעברו את הירדן, משקבלו עליהם את השבועה בהר גרזים ובהר עיבל, ונעשו ערבים זה לזה:
@23 **ושב ה' אלהיך את שבותך.** היה לו לכתוב והשיב את שבותך, רבותינו למדו מכאן שהשכינה כביכול שרויה עם ישראל בצרת גלותם, וכשנגאלין הכתיב גאלה לעצמו, שהוא ישוב עמהם. ועוד יש לומר, שגדול יום קבוץ גליות ובקשי, כאלו הוא עצמו צריך להיות אוחז בידיו ממש איש איש ממקומו, כענין שנאמר (ישעיה כז, יב) ואתם תלקטו לאחד אחד בני ישראל, ואף בגליות שאר האמות מצינו כן (ירמיהו מח, מז) ושבתי שבות מואב:
@31 **לא נפלאת היא ממך.** לא מכסה היא ממך, כמו שנאמר (דברים יז, ח) כי יפלא, ארי יתכסי, (איכה א, ט) ותרד פלאים, (איוב מ, יג) ותרד במטמוניות. מכסה, חבוש בטמון:
@32 **לא בשמים היא.** שאלו היתה בשמים, היית צריך לעלות אחריה וללמדה:
@34 **כי קרוב אליך.** התורה נתנה לכם בכתב ובעל פה:
@35 **את החיים ואת הטוב.** זה תלוי בזה, אם תעשה טוב הרי לך חיים, ואם תעשה רע הרי לך המות. והכתוב מפרש והולך היאך:
@36 **אשר אנכי מצוך היום לאהבה.** הרי הטוב, ובו תלוי: **וחיית ורבית.** הרי החיים:
@37 **ואם יפנה לבבך.** הרי הרע:
@38 **כי אבד תאבדון.** הרי המות:
@39 **העדתי בכם היום את השמים ואת הארץ.** שהם קימים לעולם וכאשר תקרה אתכם הרעה יהיו עדים שאני התריתי בכם בכל זאת. דבר אחר, העידתי בכם היום את השמים וגו' , אמר להם הקדוש ברוך הוא לישראל, הסתכלו בשמים שבראתי לשמש אתכם, שמא שנו את מדתם, שמא לא עלה גלגל חמה מן המזרח והאיר לכל העולם, כענין שנאמר (קהלת א, ה) וזרח השמש ובא השמש, הסתכלו בארץ שבראתי לשמש אתכם, שמא שנתה מדתה, שמא זרעתם אותה ולא צמחה, או שמא זרעתם חטים והעלתה שעורים, ומה אלו שנעשו לא לשכר ולא להפסד אם זוכין אין מקבלין שכר ואם חוטאין אין מקבלין פרענות, לא שנו את מדתם, אתם, שאם זכיתם תקבלו שכר, ואם חטאתם תקבלו פרענות על אחת כמה וכמה: **ובחרת בחיים.** אני מורה לכם שתבחרו בחלק החיים, כאדם האומר לחברו בחר לך חלק יפה בנחלתי, ומעמידו על חלק היפה ואומר לו, את זה ברור לך, ועל זה נאמר (תהלים טז, ה) ה' מנת חלקי וכוסי אתה תומיך גורלי, הנחת ידי על גורל הטוב לומר את זה קח לך:

@1 **אתם נצבים**. צריך לדעת כוונת מאמר זה, עוד למה הוצרך לפרט **ראשיכם** וגו' **טפכם** וגו' ולא הספיק לומר בדרך כלל כלכם. עוד צריך לדעת טעם הברית הזה הלא בסמוך אמר אלה דברי הברית, ואם רצה לכלול גם האמור בפרשה זו בכלל הברית היה לו להקדים הדברים ויאמר על הכל אלה דברי הברית:
@1 **ונראה** כי כוונת משה בברית זה הוא להכניסם בערבות זה על זה כדי שישתדל כל אחד בעד חברו לבל יעבור פי ה' ויהיו נתפסים זה בעד זה, והעד הנאמן מה שגמר אומר הנסתרות לה' אלהינו והנגלות לנו וגו' הרי שעל הערבות מדבר הכתוב, ואין זה הברית שאמר בסוף פרשת תבא כי אותו ברית הוא על עצמן, וזה שיתחייב כל אחד על אחיהו העברי כפי היכולת שביד כל אחד:
@1 **ומעתה** באנו להבין מאמר **אתם נצבים** שהכוונה הוא על דרך אומרו (רות ב') הנצב על הקוצרים ל' מינוי, ואומרו **כלכם** פירוש כולם יש עליהם עול זה כל א' לפי מה שהוא על דרך אומרם ז''ל במסכת שבת (נ''ד:) כל מי שיש בידו למחות בכל העולם נתפם על כל וכו' וכל מי שיש בידו למחות באנשי עירו נתפם על אנשי עירו, וכל מי שיש בידו למחות בבני ביתו נתפס על וכו', והוא מה שפרט הכ' כאן ואמר **ראשיכם** וגו' שכל אחד יתחייב כפי מה שיש בידו, ראשיכם הם הגדולים שבכולן שיכולין למחות בכל ישראל אלו יתחייבו על הכל, שבטיכם כל שבט ושבט יתחייב על שבטו, ז **קניכם ושוטריכם** כל זקן יתחייב על משפחתו, **כל איש ישראל** הם ההמון כל אחד יתחייב על בני ביתו, לזה הפסיק הכתוב כאן וסדר **טפכם** וגו' בפני עצמם כי אלו אחרים נתפסים עליהם שהם הרשומים בפסוק שלפניו כל אחד כפי מה שהוא, ואין הם נתפסים על אחרים, שהטף אינם בני דעה, והנשים כמו כן, הגרים גם כן אין להם להשתרר על ישראל, וכמו שדרשו ז''ל (יבמות מ''ה:) בפסוק (לעיל י''ז ט''ו) שום תשים עליך וגו' כל משימות שאתה שם עליך לא יהיה אלא מקרב אחיך ולא גרים, אבל ישראל חיבין עליהם כאומרם ז''ל (נדה י''ג) קשים גרים לישראל כספחת ופירשוהו לפי שאינם מלמדים אותם ככל הצורך, הא למדת שנתפסים עליהם:
@1 **עוד** רמז באומרו **אתם נצבים** וגו' לפני ה' לפי שכל שהוא מרוחק מהקדושה קומתו נמוכה וראשו שפלה (ב''ר פי''ב ו'), לזה אמר כי להיות לפני ה' נצבו ונשאו ראשם:
@3 **לעברך בברית וגו' ובאלתו**. טעם אומרו **ובאלתו** ולא הספיק בברית, יתבאר בהעיר עוד למה מעיקרא הוצרך לברית ולא הספיק גזירת מלך במורא העונשים הכתובים בתורה. אכן טעם הדבר הוא לפי שתבא הסברא לאדם לומר שיעבור עבירה אחת והוא שימרוד בעיקר ויענש עונש א' על עבירה אחת, ויותר נכון הוא לו מהיות מודה בה' ובתורתו ויתחייב על ל''ו כריתות וכמה מיתות ועונשים, אשר על כן נתחכם ה' והעבירם בברית לחייבם על כל פרט ופרט, וביאר השבועה שהוא על זה הדרך שנשבעין לקיים כל דבר ואם יעברו ויבטלו אחד מהם תבא עליו האלה הכתובה, והוא אומרו **בברית** וגו' **ובאלתו**, ומעתה הגם שיחשבו לכפור בעיקר לא יספיק להם עונש אחד על עון זה ויתחייבו על כל עון ועון ככל אלות הברית:
@4 **למען הקים אותך וגו'**. פירוש טעם שאני מבקש להרבות בעונשים ובאלות הוא למען הקים אותך לו לעם ולא תכפרו בו כי תפחדו מעוצם האלות אשר תתחייבו שתכפרו באלהותו ובזה תתקיימו לעם ה':
@4 **עוד** ירצה לתת טעם לברית הערבות, שלא יאמר אדם למה יעשה ה' כה לעבדיו להכביד עולם לחייבם במעשה הזולת, לזה אמר כי אלהים חשבה לטובה למען הקים אותך לו לעם פירוש שזולת זה יהיו ישראל חוזרים לאחוריהם היום יפשע אחד בקלה ולמחר בחמורה והיו נשמטים מעדת הקדושה מעט מעט עד שיפשע ישראל מהיות עם ה', ובמה שעשאם ערבים יתנו לב לעובר עבירה אחת קלה כבחמורה ויתקיימו לעם סגולה, הא למדת שכל מעשה ה' אינו אלא לטובתינו להקימנו:
@5 **ולא אתכם לבדכם וגו' כי את אשר וגו'**. קשה למה הוצרך לומר ולא אתכם וגו' ולא הספיק באומרו את אשר ישנו וגו' שהם אותם שהיה מדבר עמהם ואת אשר וגו' ומובן הדבר שלא אתם לבדם הוא כורת וגו'. אכן כוונת הכתובים הוא שבא לחייבם לקבל עליהם הברית והאלה ועל זרעם הבאים אחריהם עד עולם, והוא אומרו **ולא אתכם לבדכם** פירוש לחייב אתכם לבד אני כורת אלא בין אותם שהם עמנו בין אותם וגו', ומעתה אם לא היה אומר אלא את אשר וגו' ואת אשר וגו' אנכי כורת לא היה נשמע אלא שה' מחייב גם הבאים אחריהם אבל אינו מחייב את אשר ישנו עומד שם על זרעם אחריהם, ומאומרו לא אתכם לבדכם גילה כוונתו שבאלה עצמה שכורת עם העומדים שם מוסיף לחייבם על הדורות, ושיעור הכתוב הוא **לא אתכם לבדכם** אני מחייב על האמור אלא אף על דורות הבאים אחריכם, וזה לא היה נשמע אם לא היה אומר אלא את אשר וגו' ואת אשר וגו' אנכי כורת ברית, שהייתי אומר שהם דברי ה' על הבאים אחריהם לא שיתחייבו העומדים שם לקבל עליהם בעד הבנים:
@7 **כי אתם ידעתם וגו'**. צריך לדעת לאיזה דבר נותן הכתוב טעם כי אתם ידעתם, ורמב''ן ז''ל פירש שהוא טעם להאמור אחריו בסמוך פן יש בכם וגו', והוא קצת דוחק להקדים טעם למה שעתיד לומר אחרי כן, ואולי שדבר הכתוב בסדר זה להעיר דבר אחד, והוא כי לפי שהצריכם הכתוב להכנס לחייב עמהם גם הבאים אחריהם יאמר האומר ששורת הדין מנגדת הדבר שהרי אין חבין לאדם שלא בפניו ולא תועיל קבלה זו שיקבלו האבות על הבנים, לזה אמר **כי אתם ידעתם** וגומר **ותראו** וגו' פירוש ראיתם שאינם אלא שקץ ותועבה, ומעתה אינכם אלא זוכים להם לרחקם מתועבות הגוים ולבחור באלהים חיים ויכולין אתם לחייבם כמותכם, והוא מה שדקדק לקרותם שקוציהם וגלוליהם לומר שידעו והשכילו השפלתם ומא ים ותם:
@9 **פן יש בכם וגו' ללכת לעבוד וגו'**. כאן הזהיר הכתוב על מחשבת עבודה זרה שמזהיר כאומרו פן על אשר לבבו פונה ללכת לעבוד וגו':
@9 **פן יש בכם וגו' שורש וגו'**. צריך לדעת מה הוא השורש פרה ראש וגו', אם חוזר לאשר לבבו פונה וגו' האמור בסמוך לא היה לו לומר פן יש בכם פעם ב' אלא היה לו לומר על זה הדרך פן יש בכם איש וגו' שורש פרה ראש ולענה אשר לבבו וגו', עוד צריך לדעת כוונת הדברים עצמן של **שורש פרה** וגו' שנראה שאינו פרה ראש ולענה, אלא שורש עוד צריך לדעת ברכה זה שמתברך זה השורש פרה ראש בלבבו במה מתברך, עוד אומרו לאמר, עוד נתינת טעם זה שאומר כי בשרירות וגומר, ומה הוא אומרו למען וגומר:
@9 **אכן** כוונת הכתוב הוא לבל יחשוב אדם בדעתו להקל מעליו עול העונש ויסבור בדעתו שאינו עושה עול בזה אלא משתדל בשכלו לבל יתחייב בכל הקללות ולעולם אינו חושב בדעתו לעבור פי ה' גדולה וקטנה, וכנגד זה אמר הכתוב **פן יש בכם שורש פרה ראש ולענה** פירוש שעתה אינו אלא שורש, ומודיע שממנו יפרה ראש ולענה כאשר אבאר, ופירש הכתוב מה הוא השורש ואמר והיה בשמעו את דברי האלה, אמר **והיה** לשון שמחה כי ישמח בשומעו שהדבר חיובו הוא מצד האלה שזה יגיד שזולת האלה לא יתחייב, **והתברך בלבבו** יבטח שלא תבא עליו הקללה בסיבת לבבו על זה הדרך, **לאמר** פירוש יאמר שלום יהיה לי כי בשרירות וגו' פירוש הגם שישביעם משה ויענה אמן הוא יבטלנו בלבו, והעיקר בשבועה הוא הלב, וכדברי ר' עקיבא שאמר (שבועות כ''ו) האדם בשבועה שצריך שיהיה לבו ופיו שוים, וכל שמבטל בלבו הגם שמוציא בשפתיו אין אנו הולכים אלא אחר מחשבת הלב, והוא אומרו **כי בשרירות לבי אלך** כי העיקר שתלוי בו ענין השבועה הוא הלב ולזה כינה לו השרירה, ובמה שלא יקבל השבועה בלבו לא יתחייב כל העונש האמור בין על עצמו לא יתחייב אלא עונש עבירה אחת כמו שכתבנו, בין הבנים בניו לא יחייבם בכח שבועתו, בין בענין הערבות על הזולת, והוא אומרו **למען ספות הרוה את הצמאה** פירוש ספות ל' כריתה, ופירוש רוה הוא כינוי לריבוי, וצמאה הוא כינוי למועט, והכוונה שמתחכם לכרות ריבוי העונש לעשותו מועט במה שמבטל בלבו השבועה:
@9 **ודבר** זה קראו משה שורש, שממנו יפרה ראש ולענה, הטעם כי כלום עיקר טעם השבועה הוא, כדי שבזה יתחזק נגד המחטיא, כדרך אומרו (תהלים קיט קו) נשבעתי ואקיימה, וכמעשה בועז שנשבע ליצרו (במדב''ר טו טז). ולזה אדם שחושב מחשבה זו הוא פיתוי בחינת הרע, שמשריש בו שורש רע, כדי שאחר כן יהיה נקל להשריש במעיו שורש רשע להתעיב מעשיו, ויאמר אליו כלום הדבר תלוי אלא בשבועה, אתה לא נשבעת, קום עשה לך אלהים ועשה אשר תתאו עשות:
@9 **וקרא** למעשה הרע ראש ולענה, לצד שהעבירות טעמם ראש ולענה, והוא סוד טיפה מרה שבחרב מלאך המות (ע''ז כ:), שתתהוה מעבירות האדם, בסוד תיסרך רעתך (ירמיה ב יט), ולהיפך במעשה הטוב בסוד טעמו וראו כי טוב ה' (תהלים לד ט):
@9 **וייחד** הכתוב עונש לזה יתר על המקבלים הברית, ואמר לא יאבה וגו', פירוש הגם שה' מדתו היא למחול ולסלוח לעונות עמו ישראל כשמחלין פניו כידוע, זה האיש לא יאבה ה', אמר לשון זה לא יאבה, נתכוין לומר שה' יהפוך בו רצונו שסולח ולא יאבה לסלוח. והיוצא מדבר זה כשלא יאבה ה' סלוח לו, הוא כי אז יעשן אף ה', אומרו אז, פירוש כשיחטא אחר כך שפרה ראש ולענה אז במקום שחשב להקל עונשו, ונהפוך הוא שיעשן אף ה' וקנאתו באיש ההוא ורבצה בו כל האלה הכתובה בספר הזה:
@9 **ונמצא** כי מלבד שלא הרויח כלום במחשבתו הרעה שהרי כל הרעה תבואנו, עוד לו שתרבוץ בו כל האלה, מה שלא יהיה לו כן אם יקבל השבועה עתה, שהגם שיתחייב בה בבוא עליו הרע ויקרא אל ה' יסלח לו, ולא תרבוץ בו כל האלה, כיון שעשה מה שעליו וקבל האלה עתה, אלא שהתנצח מיצרו ירחמהו עושהו, מה שאין כן אדם הבליעל שיבטל השבועה עתה בלבו שהוא מקשה עצמו לדעת וגורם רעה לעצמו:
@9 **והנה** הגם שאמר הכתוב באיש ההוא, הוא הדין משפחה, או שבט, וכמו שגילה הכתוב לבסוף כאומרו (פסוק כא) ואמר הדור האחרון וגו' וראו את מכות הארץ ההיא וגו', הרי כי לא לאיש אחד ייחד עונש האמור, אלא גם לרבים אשר יזמו ככה:
@9 **ואומרו ומחה ה' את שמו מתחת השמים**. דע כי שורש נשמות עם בני ישראל יסודתם בהררי קודש תחת השמים, בסוד השמים כסאי (ישעיה סו א), והנשמות הם חצובות מתחת כסא כבודו יתברך, והבן:
@9 **וכבר** ידעת סוד השם כי הוא הנשמה, וכמו שהארכנו במקומות אחרים, ואמר הכתוב על המשתרר בלבבו ומחה ה' את שמו, שהיא נשמתו, משורשה, שהוא תחת השמים, וזו היא כריתות הנפש משרשה:
@12 ואומרו **והבדילו ה' לרעה**. קשה אחר שמחה ה' את שמו מה מקום להבדלה. אכן לפי מה שקדם לנו כי כל נשמות עם בני ישראל שורש אחד להם כאומרו (ישעיה ס כב) נצר מטעי, וכמו שרמזו רבותינו ז''ל (ויק''ר ד ו) בפסוק (כל הנפש הבאה לבית יעקב וגו') [ויהי כל נפש יוצאי ירך יעקב שבעים נפש] (שמות א ה) שהגם שהם שבעים קראם נפש, לצד בחינת השורש:
@12 **לזה** כשאמר הכתוב ומחה ה' את שמו, ביאר הכתוב שלא ישלוט עליו חלק הרע לאבדו לאיש המשתרר בלבו עד שיבדילו ה', ויגביל החלק שישלוט בו הרצועה רעה, כי הקליפה השולטת תקרא רעה, וכן היא מדת ה' כשנתן רשות למחבל מגביל לו מקום אשר ישלוט בו. וצא ולמד ממעשה רבא (תענית כד:) כשהטריח לה' כביכול לעשות נם שצוה עליו אביו לבל יישן במקומו ושלטו המחבלים במטתו ולא חוץ ממנה והוא מטעם זה עצמו:
@12 **ואומרו מכל שבטי ישראל**. לפי שהנפש מסתבכת עם כל השבטים, לזה יבדילהו מכולם לבל תגיע רעתו לזולתו:
@12 **או** יאמר על זה הדרך והבדילו וגו', פירוש שאחר שימחה ה' את שמו שהיא נשמתו, יבדילו לרצועה הרעה, להומו ולאבדו בכוסות המרים אשר מוכנים לו, והוא אומרו ככל אלות וגו', לומר שהרעה שישלוט ה' עליו, היא רעה שכוללת כל האלות אשר נתחכם הוא להמלט ממנה:
@13 **ואמר הדור וגו' וראו וגו'**. קשה למה הקדים האמירה לראיה, שעליה הם אומרים, שהיה לו לומר וראו הדור האחרון וגו' והנכרי וגו' ואמרו וגו', ומה גם שלא היה צריך לומר ואמר וגו' שהרי הוא אומר אחר כך ואמרו וגו'. עוד למה התחיל לדבר לשון יחיד וגמר אומר ואמרו לשון רבים, ואמרו כל הגוים:
@13 **ונראה** שכוונת הכתוב הוא על זה הדרך, ואמר הדור האחרון שהם בניכם, והוצרך לפרט לפי שיש דורות מהאומות, ולא הוא בלבד אמר אלא גם הנכרי אשר יבא וגו', פירוש נכרי הסמוך וגם הבא מארץ רחוקה, וכאילו אמר ואשר יבא וגו' וראו פירוש הנכרים ההם קרוב ורחוק את מכות הארץ וגו':
@13 **ואמרו** כל הגוים, גם הם נוסף על מאמר הדור האחרון בניכם וגו' על מה עשה וגו', והזכיר וראו בנכרים ולא בדור האחרון בניהם, לפי שאלו מצויים הם במחוז ישראל ורואים הנעשה, ולא הוצרך לומר בו וראו, ואומרו כל הגוים, יודיע הכתוב כי הרואים יגידו לכל את אשר הפליא ה' עשות בעיר ההיא:
@13 **וכל** מאמר זה הוא כנגד חלוקה ראשונה שהזכיר הכתוב פן יש בכם איש וגו' או משפחה או שבט וגו' ללכת לעבוד וגו', לפי שהקללות שיחד עד עתה היו כנגד חלוקה ב' בעל שורש פורה ראש ולענה וכבר מחה את שמו מתחת השמים, ומכאן הוא מתחיל עונש הראשון וראו את מכות וגו':
@13 **ואומרו על אשר עזבו וגו'**, **וילכו ויעבדו וגו'**. כרשום בתחילת המאמר ללכת לעבוד, ולזה לא אמר ומחה ה' את שמם אלא שממון ארצם ולהגלותם מעל אדמתם וישליכם אל ארץ אחרת וגו':
@20 **הנסתרת וגו' והנגלת**. פירוש היא תשובת ישראל למשה, שהנסתרות לא יתחייבו בהם, אבל הנגלות קיימו וקבלו עליהם הערבות. ואומרו ולבנינו עד עולם, כאן קבלו עליהם ועל זרעם אחריהם כמו שהתנה משה בפסוק (יג) ולא אתכם וגו' כמו שפירשנו:
@21 **והיה כי יבאו עליך כל הדברים וגו'**. צריך לדעת למה הוצרך לומר כל הדברים האלה, ולא הספיק באומרו כי יבואו עליך הברכה והקללה אשר נתתי לפניך:
@21 **ואולי** שיכוין על דרך אומרם ז''ל במסכת ברכות (נד.) חייב אדם לברך על הרעה כשם שהוא מברך על הטובה, והעמידוהו בגמרא (שם ס:) לקבל הרעה בשמחה כדרך ששמח על הטובה:
@21 **והוא** אומרו והיה שהוא לשון שמחה (ב''ד מב ג), כי יבואו עליך כל הדברים תקבלם בשמחה, בהשואה יחד הברכה והקללה, ואם היה אומר כי יבואו עליך הברכה והקללה אשר נתתי לפניך, היה נשמע הכתוב על זה הדרך, והיה שהוא השמחה כי יבואו עליך הברכה, ותיבת והקללה נמשכת עם מאמר אשר נתתי לפניך שלאחריה, ולא הייתי יודע שחוזר מאמר והיה גם על הקללה:
@21 **עוד** הצצתי ואראה מה נעמה חיבת הקודש אשר חבב אלהינו אותנו, הלא תראה כי בזכרון הברכה הגיע אותה עלינו, ואמר כי יבואו עליך הברכה, ובזכרון הקללה אמר והקללה אשר נתתי לפניך ולא עליך, ולטעם זה אמר אשר נתתי לפניך, ולא הספיק במאמר כל הדברים האלה:
@21 **גם** אם היה אומר כי יבואו עליך הברכה והקללה אשר נתתי לפניך, הייתי מפרש מאמר אשר נתתי לפניך על שניהם, אבל מאומרו כל הדברים האלה גילה בזה יתור אשר נתתי לפניך, שבא להבדיל בין הברכה לקללה כמו שפירשתי, ולדרך זה אומרו כל הדברים האלה, חוזר אל הברכה האמורה בסמוך לה, ואל ירע בעיניך אומרו הדברים לשון רבים, והברכה לשון יחיד, כי הרבה דברים טובים נכללו בברכה:
@21 **הברכה והקללה**. פירוש לא מיבעיא בעוד הטובה עליהם, אם הרשיעו וחזרו בתשובה שיהיו מרוצים אל ה', אלא אפילו אחר שנמאסו בעיני ה' ושלח בם חרון אפו והדיחם מעל פניו, ולצד הצרה אשר תסובבם חוזרים בתשובה, כאומרו והשבות וגו' בכל הגוים, אף על פי כן ישיב ה' שבותם:
@21 **ויש** להעיר למה הוצרך לומר הברכה, כיון שדבר הסובב התשובה הוא מורא הקללה, לא היה לו לומר אלא כי יבא עליך הקללה. ונראה כי בא להעיר דבר שבו ישיב אל לבו לשוב בתשובה, והוא כי ישכיל בהטיבו מעשיו לפני ה' ברוך הוא הברכה אשר תסובבנו, ועת אשר יסור מני אורח החיים הקללה אשר תבואהו, ומזה ישכיל להשיב אל לבו, כי זולת מבחן הברכה שיהיה בה בעשות רצונו יתברך, לא יצדיק סיבת הקללה שהיא לצד עוזבו את ה':
@21 **והשבת אל לבבך**. פירוש לצד שהרשעים לבבם טועה, לזה אמר והשבות אל לבבך שניהם הטועים בדרך לא טוב, ואומרו בכל הגוים וגו' פירוש בכח טענת היותו גולה ונידח בכל הגוים, ויאמר ללבו ראה מה גרמו מעשי הרעים וידע כי רע ומר עוזבו את ה', והוא אומרו והשבות אל לבבך בטענת כל הגוים אשר הדיחך ה' שמה, וכאילו אמר כאשר הדיחך ה' בכל הגוים:
@21 **וטעם** שדיבר הכתוב בדרך זה, להיות שימצא המסית טענה לסתור הוכחת הגליות, באומרו כי הלא כמה וכמה מהאומות שיקרה להם כזה שיגלו מעל אדמתם, לזה אמר בכל הגוים, כי אין גלות כגלות ישראל אשר נתפזרו בארבע רוחות העולם, והוא אומרו בכל הגוים אשר הדיחך ה' שמה:
@22 **ושבת עד ה' אלהיך**. אומרו ושבת, ולא הספיק במה שאמר והשבות אל לבבך, לפי מה שפירשתי כי והשבות אל לבבך וגו' הוא טענת הנצחון ללבו הטועה, וזה לענין להכיר כי לא טוב עשה, והתשובה לפני ה' להטיב דרכיו הוא מאמר ושבת עד:
@23 **ושב ה' וגו'**. פירוש חלקי הקדושה שנשבו מצד מעשיך הרעים שקדמו, ישיבם ה' מהשבאי, זה כנגד גאולת שבית הנעלם, וכנגד שבית הנגלה אמר ושב וגו':
@26 **ומל ה' אלהיך וגו'**. יש להעיר אחר שאמר למעלה ושבת עד ה' ושמעת בקולו, מה מקום לומר עוד ומל ה'. עוד רואני שאומר עוד אחר כך ואתה תשוב וגו', שנראה שמה שקדם עדיין לא הגיע לתשובה, וזה אינו, כי אחר שמל לבו לאהבה את ה' בכל לבו ובכל נפשו, אין לך תשובה גדולה מזו:
@26 **אכן** לפי מה שפירשתי בפרשת כי תבא (לעיל כח טו) בין בענין הברכות בין בענין הקללות שיש שלשה דברים כלליות במצות ה', א' היא עסק התורה, שנית שמירת מצות לא תעשה, שלישית קיום מצות עשה:
@26 **לזה** כשבא לומר תיקון התשובה סדר שלשתם, כנגד תשובת תלמוד תורה, אמר תשובה ראשונה ושבת עד ה', וגמר אומר ושמעת בקולו שהוא תלמוד תורה, ולא הזכיר עמו דבר אחר, וזו היא התחלת התשובה שצריך השב עשות, ואמר כנגדה ושב ה' את שבותך ושב וקבצך וגו', כאומרם ז''ל (זוה''ק ח''ג ער.) שבזכות עסק התורה יהיו ישראל נגאלין. גם אמר על מה אבדה הארץ וגו', ויאמר ה' על עזבם את תורתי (ירמיה ט יא יכ), לזה כשישובו לתלמוד תורה יקבצם ה' ויביאם אל הארץ אשר ירשו וגו':
@26 **וכנגד** שמירת מצות לא תעשה אמר ומל ה' אלהיך את לבבך וגו', וידוע כי ערלת הלב הוא עשות רשע ואהבת הרשע, שלבו של אדם מחמדתו, וכנגדו אמר ומל וגו' לאהבה את ה', פירוש שתלביש האהבה אשר תיכן בך התוכן בריאתך בנעימות ידידות חיבת אלהיך, ויחד שכר לזה שיהפוך ה' כל הצרות מעלינו על שונאינו כאומרו ונתן וגו' על אויביך וגו':
@26 **וכנגד** קיום מצית עשה, אמר ואתה תשוב וגו' ועשית את כל מצותיו הרי זה מצות עשה, ויחד להם שכר הקרבת התועלת כאומרו והותירך וגו' וישוב לשוש וגו':
@31 **כי המצוה וגו' אשר אנכי מצוך וגו'**. צריך לדעת אומרו היום. עוד אומרו לא נפלאת וגו' ולא רחוקה, הלא בכלל ההפלאה היא ההרחקה. עוד אומרו ולא מעבר לים וגו', בשלמא אומרו לא בשמים היא דכר נמנע מהשגה, כי מי יעלה השמימה, אבל מעבר לים הלא אניות יעברו ויקחוה, הגם שתהיה באיי הים הרחוקים מאד:
@31 **ואולי** שיכוין הכתוב לשני פרטי המניעה, א' מצד השגת ידיעת התורה עצמה, ושניה מצד קיום מצותיה. כנגד מניעת ידיעת התורה אמר לא נפלאת היא וגו', וחזר ופירש מה היא ההפלאה ואמר לא בשמים וגו', כנגד העדר השגתה אמר לא בשמים היא וגו' כאשר היתה בתחילה, שהרי משה עלה בשמים ולקחה לנו, והנה היא לפנינו:
@31 **וכנגד** מניעת השגת קיום מצותיה אמר ולא רחוקה, וחזר ופירש מה הוא הריחוק, ואמר ולא מעבר לים היא לאמר וגו', פירוש כמו שאירע למשה שהגם שעלה שמים והוריד התורה נמנעו ממנו השגת קיום מצותיה התלויות בארץ, שהם כמה וכמה כמעט רובי תורה, מה שאין כן הם שהשיגו לעבור הים לבא אל הארץ לקיים מצוותיה:
@31 **והגם** שאמר מי יעבר לנו אל עבר הים ויקחה לנו, כלל יחד מניעת השגתה עם מניעת קיום מצותיה, ולעולם עיקר הדבר שנתכוון אליו במעבר לים הוא על מניעת קיום מצותיה:
@31 **ודקדק** לומר היום, פירוש בזמן שהיו סמוכים ליכנס בארץ שאז היה קרוב אליהם הדבר לעשות, וקרא לירדן ים לפי שנשפך לתוך ים המלח כאמור ביהושע (ג טז) והיורדים על ים הערבה ים המלח תמו נכרתו:
@39 **העדתי בכם וגו'**. פסוק זה מיותר שהרי אמר בסמוך ראה נתתי לפניך היום את החיים ואת הטוב וגו'. עוד צריך לדעת למה שינה מסדר שאמר למעלה שעושה חלוקת הטוב בפני עצמו כאומרו (פסוק טו) את החיים ואת הטוב את המות ואת הרע, וכאן אמר החיים והמות וגו' הברכה והקללה. עוד צריך לדעת למה לא אמר אלא ובחרת בחיים, ולא אמר ואת הטוב:
@39 **ונראה** בהעיר למה הפסיק במאמר נתתי לפניך בין מאמר החיים והמות, למאמר הברכה והקללה, שהיה לו להקדים ולומר נתתי לפניך החיים וגו', או אחר שיאמר והקללה יאמר נתתי לפניך:
@39 **אכן** כוונת הכתוב היא להעיר, כי שני יעודים אחד טוב ואחד רע הם בעולם הזה. ולזה אמר בפסוק זה החיים והמות נתתי לפניך, פירוש שכר ועונש הנתונים לפניך, פירוש בעולם הזה, הם החיים והמות, אם יטיבו יחיו, ואם ירשיעו ימותו, אלו השנים הם לפניך בעולם הזה:
@39 **ויש** שנים אחרים, והם הברכה והקללה, הם יעודים לעולם הבא, ואינם לפניו אלא לאחר מיתה, על דרך אומרו (לעיל כח ו) ברוך אתה בבואך וברוך אתה בצאתך, ולהיפך ארור הוא וגו', ואמרו רבותינו ז''ל (כ''מ קז.) שמדבר על יציאתו מן העולם, ולזה הפסיק במאמר נתתי לפניך בין שני יעודים הראשונים לשנים האחרונים:
@39 **ולזה** גמר אומר ובחרת בחיים, שהוא יעוד עולם הזה, כי יתקרב לב האדם ביותר למה שלפניו, כדרך אומרו (לעיל יא יג) והיה אם שמוע תשמעו וגו' ונתתי מטר ארצכם, הרי שלא הזכיר להטות לבב אנוש אלא בדברים הנגלים בעולם הזה:
@39 **כמו** כן אמר כאן ובחרת בחיים, פירוש יתחייב הדבר אפילו כפי טבע הגשמי לבחור בחיים, והגם שבפסוק שלפני זה (פסוק טו) אמר ראה נתתי לפניך החיים והטוב יחד, שם נתכוון במאמר לפניך לבחור בהם, וכאן נתכוון במאמר לפניך לומר מה שלפניך, והעיר על זאת הכוונה במה שסדרה באמצע היעודים כמו שפירשתי, גם במה שגמר אומר ובחרת בחיים כמו שפירשתי:
@40 **לאהבה את ה' וגו'**. מאמר זה סמוך עם מה שלמעלה ממנו, שאמר למען תחיה אתה וזרעך, וגמר אומר לאהבה וגו', פירוש שטעם חפץ בחיים הוא לאהבה את ה' לשמוע בקולו וגו', ונתן טעם כי הוא חייך, כי מה לאדם חיים אם לא רצונו יתברך, שעשיית רצונו היא תסובב שידבק האדם בקונו, כאומרו ולדבקה בו, וזה הוא עצמו החיים בעולם הזה ואורך ימים לעולם הבא, והוא אומרו ואורך ימיך:
@40 **ואומרו לשבת על וגו'**. כאילו אמר ולשבת וגו', ודבר זה גם כן הוא מהשגת השלימות, כי ישיבת הארץ היא מצוה כוללת כל התורה, צא ולמד ממאמרם ז''ל (כתובות קיא.) שכל ההולך בה ארבע אמות יש לו חלק לעולם הבא שכולו חיים:
@40 **חסלת פרשת נצבים**
